// Step 32: Glass sign-in cards, Studio sign-in card, centred welcome page.
// Needs Step 31 first. Run from the project folder (next to package.json):  node setup-step-32.mjs
//
// What changes (phone and computer):
// - Log in / sign up: one frosted-glass card in the middle of the screen, over soft green light.
//   An X at the top left goes back to the welcome page (no more "<- Me"). No tab bar behind it.
// - Studio sign-in: the same card, with the MS logo and "Admin Control Center" at the top.
//   Its X goes back to the app's log-in page. The 2-step code screens use the card too.
// - Welcome page (/): content sits in the middle of the screen; "I have an account · Log in" is now a white button.
// - The log-in pages move from src/app/(app)/account to src/app/(auth)/account (the address stays /account).
//
// Try it:  npm test   then   npm run dev   and open  /  ,  /account  and  /studio
// Happy with it?  git add -A && git commit -m "Step 32: Glass sign-in cards" && git push
import { mkdirSync, rmSync, writeFileSync } from "node:fs";
import { dirname } from "node:path";

// Old places of the log-in pages (moved, not deleted from the app)
const remove = [
  "src/app/(app)/account/new-password/page.tsx",
  "src/app/(app)/account/page.tsx"
];
const files = {
  "src/app/(auth)/account/new-password/page.tsx": "\"use client\";\n\nimport { useState } from \"react\";\nimport { useRouter } from \"next/navigation\";\nimport { Loader2 } from \"lucide-react\";\nimport { useToast } from \"@/components/motion/Toast\";\nimport { account, useAccount } from \"@/lib/account/useAccount\";\nimport { useT } from \"@/lib/i18n\";\nimport PasswordMeter from \"@/components/security/PasswordMeter\";\nimport AuthScreen from \"@/components/auth/AuthScreen\";\n\n/** He arrives here from the \"reset your password\" email link. */\nexport default function NewPasswordPage() {\n  const acc = useAccount();\n  const router = useRouter();\n  const showToast = useToast();\n  const t = useT();\n  const [password, setPassword] = useState(\"\");\n  const [busy, setBusy] = useState(false);\n  const [error, setError] = useState<string | null>(null);\n\n  async function submit(e: React.FormEvent) {\n    e.preventDefault();\n    setBusy(true);\n    const r = await account.setNewPassword(password, acc.status === \"signedIn\" ? acc.user.email : undefined);\n    setBusy(false);\n    if (r.error) return setError(t(r.error, r.vars));\n    showToast(t(\"New password saved\"));\n    router.push(\"/me\");\n  }\n\n  return (\n    <AuthScreen closeHref=\"/me\" closeLabel={t(\"Close\")}>\n    <div className=\"space-y-5\">\n      <h1 className=\"text-center text-2xl font-bold\">{t(\"Choose a new password\")}</h1>\n      {acc.status === \"loading\" ? (\n        <Loader2 className=\"mx-auto animate-spin text-ink-soft\" />\n      ) : acc.status !== \"signedIn\" ? (\n        <p className=\"text-center text-sm text-ink-soft\">\n          {t('This link has expired. Go to Me → Log in → \"Forgot password?\" to get a new one.')}\n        </p>\n      ) : (\n        <form onSubmit={submit} className=\"space-y-3\">\n          <input\n            type=\"password\"\n            autoComplete=\"new-password\"\n            minLength={8}\n            required\n            aria-label={t(\"New password\")}\n            value={password}\n            onChange={(e) => setPassword(e.target.value)}\n            className=\"w-full rounded-2xl bg-surface px-4 py-3 text-sm outline-none ring-1 ring-line focus:ring-2 focus:ring-forest\"\n          />\n          <PasswordMeter password={password} email={acc.user.email} lang={t.lang} />\n          {error && <p role=\"alert\" className=\"text-sm text-red-700\">{error}</p>}\n          <button disabled={busy} className=\"w-full rounded-full bg-forest py-3.5 text-sm font-semibold text-white disabled:opacity-60\">\n            {t(\"Save password\")}\n          </button>\n        </form>\n      )}\n    </div>\n    </AuthScreen>\n  );\n}\n",
  "src/app/(auth)/account/page.tsx": "\"use client\";\n\nimport { Suspense, useRef, useState } from \"react\";\nimport Link from \"next/link\";\nimport { useRouter, useSearchParams } from \"next/navigation\";\nimport { ArrowLeft, ChevronRight, Eye, EyeOff, Loader2, Lock, Mail, ShieldCheck, Smartphone } from \"lucide-react\";\nimport { useToast } from \"@/components/motion/Toast\";\nimport { account, AUTH_METHODS, useAccount } from \"@/lib/account/useAccount\";\nimport { useT } from \"@/lib/i18n\";\nimport PasswordMeter from \"@/components/security/PasswordMeter\";\nimport AuthScreen from \"@/components/auth/AuthScreen\";\nimport Captcha, { captchaOn, type CaptchaHandle } from \"@/components/security/Captcha\";\n\ntype Mode = \"signup\" | \"login\" | \"reset\";\n/** First the list of ways in (Google, phone, email); tapping one opens its own form. */\ntype View = \"choose\" | \"email\" | \"phone\";\n\nexport default function AccountPage() {\n  return (\n    <Suspense>\n      <AccountInner />\n    </Suspense>\n  );\n}\n\nfunction AccountInner() {\n  const router = useRouter();\n  const params = useSearchParams();\n  const showToast = useToast();\n  const acc = useAccount();\n  const t = useT();\n  // Log in is the default; \"Create free account\" buttons elsewhere open ?mode=signup\n  const [mode, setMode] = useState<Mode>(params.get(\"mode\") === \"signup\" ? \"signup\" : \"login\");\n  const [view, setView] = useState<View>(\"choose\");\n\n  // Where to go after signing in: ?next=/man from the welcome screen, otherwise Me\n  const next = params.get(\"next\");\n  const afterSignIn = next && next.startsWith(\"/\") && !next.startsWith(\"//\") ? next : \"/me\";\n  const done = (msg: string) => {\n    showToast(t(msg));\n    router.push(afterSignIn);\n  };\n\n  if (acc.status === \"signedIn\") {\n    return (\n      <Shell>\n        <div className=\"py-2 text-center\">\n          <p className=\"font-semibold\">{t(\"You're signed in\")}</p>\n          <Link href={afterSignIn} className=\"mt-4 inline-block rounded-full bg-forest px-5 py-2.5 text-sm font-semibold text-white\">\n            {t(\"Continue\")}\n          </Link>\n        </div>\n      </Shell>\n    );\n  }\n  if (acc.status === \"unavailable\") {\n    return (\n      <Shell>\n        <p className=\"py-2 text-center text-sm text-ink-soft\">{t(\"Accounts aren't switched on yet. You can keep using the app as a guest.\")}</p>\n      </Shell>\n    );\n  }\n\n  const signup = mode === \"signup\";\n  const switchMode = (m: Mode) => {\n    setMode(m);\n    if (m !== \"reset\" && view === \"phone\") setView(\"choose\");\n  };\n\n  return (\n    <Shell back={view === \"choose\" ? null : () => { setView(\"choose\"); if (mode === \"reset\") setMode(\"login\"); }} backLabel={signup ? \"Other ways to sign up\" : \"Other ways to log in\"}>\n      <div className=\"text-center\">\n        <h1 className=\"text-2xl font-bold\">{t(mode === \"reset\" ? \"Reset your password\" : signup ? \"Create your free account\" : \"Welcome back\")}</h1>\n        <p className=\"mt-1 text-sm text-ink-soft\">\n          {t(\n            mode === \"reset\"\n              ? \"We'll email you a link to choose a new password.\"\n              : signup\n                ? \"Keep your points, badges and progress safe, even if you change phones. Only you can see your data.\"\n                : \"Log in to see your points, badges and progress.\",\n          )}\n        </p>\n      </div>\n\n      {view === \"choose\" && (\n        <div key={mode} className=\"page-enter space-y-2.5\">\n          <button\n            onClick={async () => {\n              const r = await account.signInGoogle(afterSignIn);\n              if (r.error) showToast(t(r.error));\n            }}\n            disabled={!AUTH_METHODS.google}\n            className={way}\n          >\n            <GoogleMark /> {t(\"Continue with Google\")}\n            {!AUTH_METHODS.google && <Soon />}\n          </button>\n          <button onClick={() => setView(\"phone\")} disabled={!AUTH_METHODS.phone} className={way}>\n            <Smartphone size={18} className=\"text-forest\" /> {t(\"Continue with phone number\")}\n            {!AUTH_METHODS.phone && <Soon />}\n          </button>\n          <button onClick={() => setView(\"email\")} className={way}>\n            <Mail size={18} className=\"text-forest\" /> {t(\"Continue with email\")}\n          </button>\n        </div>\n      )}\n\n      {view === \"email\" && (\n        <div className=\"page-enter\">\n          <EmailForm mode={mode} onMode={switchMode} onDone={done} />\n        </div>\n      )}\n      {view === \"phone\" && AUTH_METHODS.phone && (\n        <div className=\"page-enter\">\n          <PhoneForm onDone={() => done(\"Signed in · your progress is saved\")} />\n        </div>\n      )}\n\n      {/* Log in ⇄ Create account */}\n      {mode !== \"reset\" && (\n        <p className=\"text-center text-sm text-ink-soft\">\n          {t(signup ? \"Already have an account?\" : \"Don't have an account?\")}{\" \"}\n          <button onClick={() => switchMode(signup ? \"login\" : \"signup\")} className=\"font-semibold text-forest\">\n            {t(signup ? \"Log in\" : \"Create one\")}\n          </button>\n        </p>\n      )}\n\n      <p className=\"flex items-start gap-2 px-1 text-xs text-ink-soft\">\n        <Lock size={13} className=\"mt-0.5 shrink-0 text-forest\" />\n        {t(\"Your check-ins and notes are private. Kayani staff can't read them, and we never use them for adverts.\")}\n      </p>\n\n      {/* For Kayani staff: the Admin Control Center has its own sign-in (with an authenticator code) */}\n      {view === \"choose\" && (\n        <Link\n          href=\"/studio\"\n          className=\"flex items-center justify-between gap-3 rounded-2xl px-4 py-3 text-xs ring-1 ring-line transition-colors hover:bg-surface\"\n        >\n          <span className=\"flex items-center gap-2 text-ink-soft\">\n            <ShieldCheck size={15} className=\"text-forest\" />\n            {t(\"Kayani staff?\")} <span className=\"font-semibold text-ink\">{t(\"Open the Studio\")}</span>\n          </span>\n          <ChevronRight size={15} className=\"text-ink-soft\" />\n        </Link>\n      )}\n    </Shell>\n  );\n}\n\nconst way =\n  \"flex w-full items-center justify-center gap-3 rounded-full bg-surface py-3.5 text-sm font-semibold ring-1 ring-line transition-transform active:scale-[0.98] disabled:opacity-50 disabled:active:scale-100\";\n\nfunction Soon() {\n  const t = useT();\n  return <span className=\"rounded-full bg-bg px-2 py-0.5 text-[10px] text-ink-soft ring-1 ring-line\">{t(\"Soon\")}</span>;\n}\n\nfunction EmailForm({ mode, onMode, onDone }: { mode: Mode; onMode: (m: Mode) => void; onDone: (msg: string) => void }) {\n  const [email, setEmail] = useState(\"\");\n  const [password, setPassword] = useState(\"\");\n  const [show, setShow] = useState(false);\n  const [busy, setBusy] = useState(false);\n  const [error, setError] = useState<string | null>(null);\n  const [sent, setSent] = useState<string | null>(null);\n  const [captcha, setCaptcha] = useState<string | null>(null);\n  const captchaBox = useRef<CaptchaHandle>(null);\n  const t = useT();\n\n  async function submit(e: React.FormEvent) {\n    e.preventDefault();\n    if (captchaOn && !captcha) return setError(t(\"Please complete the check that you're a person, then try again.\"));\n    setBusy(true);\n    setError(null);\n    const token = captcha ?? undefined;\n    captchaBox.current?.reset(); // each check works once\n    if (mode === \"reset\") {\n      const r = await account.resetPassword(email, token);\n      setBusy(false);\n      if (r.error) return setError(t(r.error, r.vars));\n      return setSent(\"If that email has an account, a reset link is on its way. Check your inbox.\");\n    }\n    const r = mode === \"signup\" ? await account.signUpEmail(email, password, token) : await account.signInEmail(email, password, token);\n    setBusy(false);\n    if (r.error) return setError(t(r.error, r.vars));\n    if (r.needsConfirm) return setSent(\"Almost done. We sent you an email: tap the link in it to finish creating your account.\");\n    onDone(mode === \"signup\" ? \"Account created · your progress is saved\" : \"Welcome back\");\n  }\n\n  if (sent) {\n    return (\n      <div className=\"rounded-3xl bg-mint/60 p-5 text-sm text-forest-deep\">\n        <Mail size={20} className=\"mb-2 text-forest\" />\n        {t(sent)}\n        <button onClick={() => { setSent(null); onMode(\"login\"); }} className=\"mt-3 block font-semibold text-forest\">\n          {t(\"Back to log in\")}\n        </button>\n      </div>\n    );\n  }\n\n  return (\n    <form onSubmit={submit} className=\"space-y-3\">\n      <label className=\"block\">\n        <span className=\"text-xs font-semibold text-ink-soft\">{t(\"Email\")}</span>\n        <input type=\"email\" autoComplete=\"email\" required value={email} onChange={(e) => setEmail(e.target.value)} className={input} />\n      </label>\n      {mode !== \"reset\" && (\n        <label className=\"block\">\n          <span className=\"text-xs font-semibold text-ink-soft\">{t(\"Password\")}</span>\n          <div className=\"relative\">\n            <input\n              type={show ? \"text\" : \"password\"}\n              autoComplete={mode === \"signup\" ? \"new-password\" : \"current-password\"}\n              required\n              minLength={mode === \"signup\" ? 8 : undefined}\n              value={password}\n              onChange={(e) => setPassword(e.target.value)}\n              className={`${input} pr-11`}\n            />\n            <button type=\"button\" onClick={() => setShow((s) => !s)} aria-label={t(show ? \"Hide password\" : \"Show password\")} className=\"absolute inset-y-0 right-0 mt-1 flex w-11 items-center justify-center text-ink-soft\">\n              {show ? <EyeOff size={16} /> : <Eye size={16} />}\n            </button>\n          </div>\n          {mode === \"signup\" && <PasswordMeter password={password} email={email} lang={t.lang} />}\n        </label>\n      )}\n      <Captcha ref={captchaBox} onToken={setCaptcha} lang={t.lang} />\n      {error && (\n        <p role=\"alert\" className=\"rounded-2xl bg-red-50 px-3 py-2 text-sm text-red-700\">\n          {error}\n        </p>\n      )}\n      <button disabled={busy} className=\"flex w-full items-center justify-center gap-2 rounded-full bg-forest py-3.5 text-sm font-semibold text-white transition-transform active:scale-[0.98] disabled:opacity-60\">\n        {busy && <Loader2 size={16} className=\"animate-spin\" />}\n        {t(mode === \"signup\" ? \"Create account\" : mode === \"login\" ? \"Log in\" : \"Send reset link\")}\n      </button>\n      <div className=\"flex justify-between text-xs font-semibold text-forest\">\n        {mode === \"login\" && (\n          <button type=\"button\" onClick={() => onMode(\"reset\")}>\n            {t(\"Forgot password?\")}\n          </button>\n        )}\n        {mode === \"reset\" && (\n          <button type=\"button\" onClick={() => onMode(\"login\")}>\n            {t(\"Back to log in\")}\n          </button>\n        )}\n      </div>\n    </form>\n  );\n}\n\nfunction PhoneForm({ onDone }: { onDone: () => void }) {\n  const [phone, setPhone] = useState(\"\");\n  const [sentTo, setSentTo] = useState<string | null>(null);\n  const [code, setCode] = useState(\"\");\n  const [busy, setBusy] = useState(false);\n  const [error, setError] = useState<string | null>(null);\n  const [captcha, setCaptcha] = useState<string | null>(null);\n  const captchaBox = useRef<CaptchaHandle>(null);\n  const t = useT();\n\n  async function send(e: React.FormEvent) {\n    e.preventDefault();\n    if (captchaOn && !captcha) return setError(t(\"Please complete the check that you're a person, then try again.\"));\n    setBusy(true);\n    setError(null);\n    const r = await account.sendPhoneCode(phone, captcha ?? undefined);\n    captchaBox.current?.reset();\n    setBusy(false);\n    if (r.error) return setError(t(r.error, r.vars));\n    setSentTo(r.phone ?? null);\n  }\n  async function verify(e: React.FormEvent) {\n    e.preventDefault();\n    if (!sentTo) return;\n    setBusy(true);\n    setError(null);\n    const r = await account.verifyPhoneCode(sentTo, code);\n    setBusy(false);\n    if (r.error) return setError(t(r.error, r.vars));\n    onDone();\n  }\n\n  return (\n    <form onSubmit={sentTo ? verify : send} className=\"space-y-3 rounded-3xl bg-surface p-4 ring-1 ring-line\">\n      {sentTo ? (\n        <label className=\"block\">\n          <span className=\"text-xs font-semibold text-ink-soft\">{t(\"Code sent by SMS to {phone}\", { phone: sentTo })}</span>\n          <input inputMode=\"numeric\" autoComplete=\"one-time-code\" maxLength={6} value={code} onChange={(e) => setCode(e.target.value.replace(/\\D/g, \"\"))} className={`${input} text-center text-lg tracking-[0.5em]`} />\n        </label>\n      ) : (\n        <label className=\"block\">\n          <span className=\"text-xs font-semibold text-ink-soft\">{t(\"Mobile number\")}</span>\n          <input type=\"tel\" inputMode=\"tel\" autoComplete=\"tel\" placeholder=\"0712 345 678\" value={phone} onChange={(e) => setPhone(e.target.value)} className={input} />\n        </label>\n      )}\n      {!sentTo && <Captcha ref={captchaBox} onToken={setCaptcha} lang={t.lang} />}\n      {error && <p role=\"alert\" className=\"rounded-2xl bg-red-50 px-3 py-2 text-sm text-red-700\">{error}</p>}\n      <button disabled={busy} className=\"flex w-full items-center justify-center gap-2 rounded-full bg-forest py-3 text-sm font-semibold text-white disabled:opacity-60\">\n        {busy && <Loader2 size={16} className=\"animate-spin\" />}\n        {t(sentTo ? \"Confirm code\" : \"Send me a code\")}\n      </button>\n      {sentTo && (\n        <button type=\"button\" onClick={() => { setSentTo(null); setCode(\"\"); }} className=\"w-full text-xs font-semibold text-forest\">\n          {t(\"Use a different number\")}\n        </button>\n      )}\n    </form>\n  );\n}\n\n/** A frosted-glass card in the middle of the screen (phone and computer). X goes back to the welcome page. */\nfunction Shell({ children, back, backLabel }: { children: React.ReactNode; back?: (() => void) | null; backLabel?: string }) {\n  const t = useT();\n  return (\n    <AuthScreen closeHref=\"/\" closeLabel={t(\"Close\")}>\n      <div className=\"stagger space-y-5\">\n        {back && (\n          <button onClick={back} className=\"-mb-1 flex items-center gap-1 text-sm text-ink-soft\">\n            <ArrowLeft size={16} /> {t(backLabel ?? \"Back\")}\n          </button>\n        )}\n        {children}\n      </div>\n    </AuthScreen>\n  );\n}\n\nfunction GoogleMark() {\n  return (\n    <svg width=\"18\" height=\"18\" viewBox=\"0 0 48 48\" aria-hidden>\n      <path fill=\"#FFC107\" d=\"M43.6 20.5H42V20H24v8h11.3C33.7 32.7 29.2 36 24 36c-6.6 0-12-5.4-12-12s5.4-12 12-12c3.1 0 5.8 1.2 7.9 3.1l5.7-5.7C34 6.1 29.3 4 24 4 12.9 4 4 12.9 4 24s8.9 20 20 20 20-8.9 20-20c0-1.3-.1-2.4-.4-3.5z\" />\n      <path fill=\"#FF3D00\" d=\"M6.3 14.7l6.6 4.8C14.7 15.1 19 12 24 12c3.1 0 5.8 1.2 7.9 3.1l5.7-5.7C34 6.1 29.3 4 24 4 16.3 4 9.7 8.3 6.3 14.7z\" />\n      <path fill=\"#4CAF50\" d=\"M24 44c5.2 0 9.9-2 13.4-5.2l-6.2-5.2C29.2 35.1 26.7 36 24 36c-5.2 0-9.6-3.3-11.3-8l-6.5 5C9.5 39.6 16.2 44 24 44z\" />\n      <path fill=\"#1976D2\" d=\"M43.6 20.5H42V20H24v8h11.3c-.8 2.2-2.2 4.2-4.1 5.6l6.2 5.2C37 39.2 44 34 44 24c0-1.3-.1-2.4-.4-3.5z\" />\n    </svg>\n  );\n}\n\nconst input = \"mt-1 w-full rounded-2xl bg-surface px-4 py-3 text-sm outline-none ring-1 ring-line focus:ring-2 focus:ring-forest\";\n",
  "src/app/(auth)/layout.tsx": "import { ToastProvider } from \"@/components/motion/Toast\";\n\n// Log in, sign up and \"choose a new password\": a full screen of their own, without the tab bar\n// or sidebar, so the sign-in card sits in the middle of the screen.\nexport default function AuthLayout({ children }: { children: React.ReactNode }) {\n  return <ToastProvider sidebar={false}>{children}</ToastProvider>;\n}\n",
  "src/app/globals.css": "@import \"tailwindcss\";\n/* `dark:` utilities follow the app's own Light/Dark/Auto setting (data-theme on <html>) */\n@custom-variant dark (&:where([data-theme=\"dark\"], [data-theme=\"dark\"] *));\n\n/* Brand tokens — Kayani Men's Social (Fernly-inspired: white, forest green, mint) */\n/* Colour modes: the \"a-\" values are the chosen colour (Green, Blue or Red, set on <html data-accent>). */\n:root {\n  /* Green (default) */\n  --a-forest: #0f5c46;\n  --a-deep: #073b2d;\n  --a-mint: #dff3ea;\n  --a-strong: #5dcaa5;\n  --a-deep-rgb: 7 59 45;\n  --a-mint-rgb: 223 243 234;\n  --a-strong-rgb: 93 202 165;\n  /* …and its night version */\n  --a-forest-dark: #17785b;\n  --a-deep-dark: #0a3328;\n  --a-bright: #6fd3ae;\n  --a-soft: #d6f3e7;\n  --a-tint-dark: #16382d;\n  --a-bg-dark: #0b1411;\n  --a-surface-dark: #131f1b;\n  --a-line-dark: #24342e;\n\n  --bg: #f4f6f4;\n  --surface: #ffffff;\n  --ink: #0f1f1a;\n  --ink-soft: #5b6b65;\n  --line: #e3e8e5;\n  --forest: var(--a-forest);\n  --forest-deep: var(--a-deep);\n  --mint: var(--a-mint);\n  --mint-strong: var(--a-strong);\n}\n[data-accent=\"blue\"] {\n  --a-forest: #1e5bb8;\n  --a-deep: #0c2a57;\n  --a-mint: #e2ecfb;\n  --a-strong: #5b9cf0;\n  --a-deep-rgb: 12 42 87;\n  --a-mint-rgb: 226 236 251;\n  --a-strong-rgb: 91 156 240;\n  --a-forest-dark: #2a6fd6;\n  --a-deep-dark: #0d2650;\n  --a-bright: #8ab8ff;\n  --a-soft: #dbe8ff;\n  --a-tint-dark: #172c4d;\n  --a-bg-dark: #0a0f17;\n  --a-surface-dark: #121a26;\n  --a-line-dark: #233046;\n  --bg: #f3f5f9;\n  --line: #e1e6ee;\n}\n[data-accent=\"red\"] {\n  --a-forest: #b3263a;\n  --a-deep: #5a0f1b;\n  --a-mint: #fbe4e7;\n  --a-strong: #f07686;\n  --a-deep-rgb: 90 15 27;\n  --a-mint-rgb: 251 228 231;\n  --a-strong-rgb: 240 118 134;\n  --a-forest-dark: #c8364b;\n  --a-deep-dark: #4a0f18;\n  --a-bright: #ff99a6;\n  --a-soft: #ffe0e4;\n  --a-tint-dark: #44181f;\n  --a-bg-dark: #140b0d;\n  --a-surface-dark: #1e1316;\n  --a-line-dark: #3a2328;\n  --bg: #f8f4f4;\n  --line: #ece3e4;\n}\n\n@theme inline {\n  --color-bg: var(--bg);\n  --color-surface: var(--surface);\n  --color-ink: var(--ink);\n  --color-ink-soft: var(--ink-soft);\n  --color-line: var(--line);\n  --color-forest: var(--forest);\n  --color-forest-deep: var(--forest-deep);\n  --color-mint: var(--mint);\n  --color-mint-strong: var(--mint-strong);\n  --font-sans: \"Plus Jakarta Sans Variable\", system-ui, sans-serif;\n}\n\nhtml {\n  scroll-behavior: smooth;\n}\n\nbody {\n  background: var(--bg);\n  color: var(--ink);\n  font-family: \"Plus Jakarta Sans Variable\", system-ui, sans-serif;\n  -webkit-tap-highlight-color: transparent;\n}\n\n/* Gentle entrance motion */\n@keyframes rise {\n  from { opacity: 0; transform: translateY(12px); }\n  to { opacity: 1; transform: translateY(0); }\n}\n.rise { animation: rise 0.5s cubic-bezier(0.2, 0.8, 0.2, 1) both; }\n.rise-2 { animation-delay: 0.08s; }\n.rise-3 { animation-delay: 0.16s; }\n.rise-4 { animation-delay: 0.24s; }\n\n/* ===== Motion kit (Fernly-style) ===== */\n\n/* 1. Page enter: whole page fades in */\n@keyframes page-in {\n  from { opacity: 0; }\n  to { opacity: 1; }\n}\n.page-enter { animation: page-in 0.35s ease-out both; }\n\n/* 1b. Stagger: each direct child rises in, one after another */\n.stagger > * { animation: rise 0.55s cubic-bezier(0.2, 0.8, 0.2, 1) both; }\n.stagger > *:nth-child(1) { animation-delay: 0.04s; }\n.stagger > *:nth-child(2) { animation-delay: 0.10s; }\n.stagger > *:nth-child(3) { animation-delay: 0.16s; }\n.stagger > *:nth-child(4) { animation-delay: 0.22s; }\n.stagger > *:nth-child(5) { animation-delay: 0.28s; }\n.stagger > *:nth-child(6) { animation-delay: 0.34s; }\n.stagger > *:nth-child(7) { animation-delay: 0.40s; }\n.stagger > *:nth-child(n + 8) { animation-delay: 0.46s; }\n\n/* 2. Bars grow upward */\n@keyframes grow-up {\n  from { transform: scaleY(0); }\n  to { transform: scaleY(1); }\n}\n.grow-bar {\n  transform-origin: bottom;\n  animation: grow-up 0.8s cubic-bezier(0.2, 0.8, 0.2, 1) both;\n}\n\n/* 3. Toast pill: pops up from the bottom, then fades away */\n@keyframes toast-in {\n  from { opacity: 0; transform: translate(-50%, 16px) scale(0.96); }\n  to { opacity: 1; transform: translate(-50%, 0) scale(1); }\n}\n@keyframes toast-out {\n  from { opacity: 1; transform: translate(-50%, 0) scale(1); }\n  to { opacity: 0; transform: translate(-50%, 8px) scale(0.98); }\n}\n.toast-in { animation: toast-in 0.32s cubic-bezier(0.2, 0.8, 0.2, 1) both; }\n.toast-out { animation: toast-out 0.25s ease-in both; }\n\n/* 4. Popup sheet: background dims + blurs, card scales in */\n@keyframes backdrop-in {\n  from { opacity: 0; }\n  to { opacity: 1; }\n}\n@keyframes sheet-in {\n  from { opacity: 0; transform: translateY(16px) scale(0.97); }\n  to { opacity: 1; transform: translateY(0) scale(1); }\n}\n.backdrop-in { animation: backdrop-in 0.25s ease-out both; }\n.sheet-in { animation: sheet-in 0.35s cubic-bezier(0.2, 0.8, 0.2, 1) both; }\n\n/* 5. Points burst: \"+15\" floats up and fades when an activity is done */\n@keyframes float-up {\n  0% { opacity: 0; transform: translateY(4px) scale(0.9); }\n  20% { opacity: 1; transform: translateY(0) scale(1.05); }\n  100% { opacity: 0; transform: translateY(-28px) scale(1); }\n}\n.float-up { animation: float-up 0.9s ease-out both; pointer-events: none; }\n\n/* Hatched (striped) bar, like Fernly's empty days */\n.hatch {\n  background-image: repeating-linear-gradient(\n    -45deg,\n    var(--line) 0 2px,\n    transparent 2px 7px\n  );\n  box-shadow: inset 0 0 0 1px var(--line);\n}\n\n/* Respect phones set to \"reduce motion\" */\n@media (prefers-reduced-motion: reduce) {\n  .rise, .page-enter, .stagger > *, .grow-bar,\n  .toast-in, .toast-out, .backdrop-in, .sheet-in, .float-up { animation: none; }\n}\n\n/* ===== Tabs: sliding strip of tabs + liquid glass tab bar ===== */\n\n/* On a computer (1024px and wider) the tabs sit in a 16rem sidebar on the left (SideNav),\n   so the pages start after it. On phones there's no sidebar. */\n:root { --side-nav: 0px; }\n@media (min-width: 1024px) {\n  :root { --side-nav: 16rem; }\n  /* Scrollbars stay slim on desktop */\n  .tab-panel, .overlay-page { scrollbar-width: thin; }\n}\n\n/* Two-column layouts on desktop: on phones the column wrappers disappear (display: contents)\n   so the cards keep their phone order and still rise in one after another.\n   (On desktop the same wrappers become columns; the cards inside still rise in.) */\n.stagger > .contents > * { animation: rise 0.55s cubic-bezier(0.2, 0.8, 0.2, 1) both; }\n.stagger > .contents > *:nth-child(1) { animation-delay: 0.08s; }\n.stagger > .contents > *:nth-child(2) { animation-delay: 0.14s; }\n.stagger > .contents > *:nth-child(3) { animation-delay: 0.20s; }\n.stagger > .contents > *:nth-child(4) { animation-delay: 0.26s; }\n.stagger > .contents > *:nth-child(n + 5) { animation-delay: 0.32s; }\n@media (prefers-reduced-motion: reduce) {\n  .stagger > .contents > * { animation: none; }\n}\n\n/* The strip: three full-screen tabs side by side. The phone's own scrolling moves it. */\n.tab-strip {\n  position: fixed;\n  /* (veils are positioned inside the strip, one page-width apart) */\n  inset: 0;\n  left: var(--side-nav);\n  display: flex;\n  overflow-x: auto;\n  overflow-y: hidden;\n  scroll-snap-type: x mandatory;\n  overscroll-behavior-x: contain;\n  scrollbar-width: none;\n  scroll-behavior: auto;\n  transition: opacity 0.15s ease-out;\n}\n.tab-strip::-webkit-scrollbar { display: none; }\n/* Each tab scrolls up and down on its own, and remembers where it was */\n.tab-panel {\n  flex: 0 0 100%;\n  height: 100%;\n  overflow-x: hidden;\n  overflow-y: auto;\n  scroll-snap-align: start;\n  scroll-snap-stop: always;\n  overscroll-behavior-y: contain;\n}\n/* Card rows that scroll sideways stop at their ends instead of dragging the whole tab along */\n.tab-panel .overflow-x-auto { overscroll-behavior-x: contain; }\n\n/* Pages that open on top of a tab */\n.overlay-page {\n  position: fixed;\n  inset: 0;\n  left: var(--side-nav);\n  z-index: 10;\n  overflow-y: auto;\n  background: var(--bg);\n  overscroll-behavior-y: contain;\n}\n@keyframes slide-from-right {\n  from { opacity: 0.6; transform: translateX(40%); }\n  to { opacity: 1; transform: translateX(0); }\n}\n.slide-from-right { animation: slide-from-right 0.34s cubic-bezier(0.2, 0.8, 0.2, 1) backwards; }\n\n/* Frosted glass bar: page shows through, blurred and a little brighter */\n.glass-bar {\n  background: linear-gradient(180deg, rgba(255, 255, 255, 0.62), rgba(255, 255, 255, 0.42));\n  -webkit-backdrop-filter: blur(22px) saturate(1.8);\n  backdrop-filter: blur(22px) saturate(1.8);\n  border: 1px solid rgba(255, 255, 255, 0.7);\n  box-shadow:\n    0 10px 30px rgb(var(--a-deep-rgb) / 0.16),\n    0 2px 6px rgb(var(--a-deep-rgb) / 0.06),\n    inset 0 1px 0 rgba(255, 255, 255, 0.9),\n    inset 0 -1px 0 rgb(var(--a-deep-rgb) / 0.04);\n}\n/* ===== Liquid Glass: the moving piece of glass in the tab bar ===== */\n.liquid-glass {\n  will-change: transform, border-radius;\n  /* a clearer, brighter piece of glass sitting on the frosted bar */\n  background:\n    radial-gradient(120% 90% at 50% 0%, rgba(255, 255, 255, 0.8), rgba(255, 255, 255, 0) 60%),\n    linear-gradient(180deg, rgba(250, 253, 251, 0.94), rgb(var(--a-mint-rgb) / 0.9));\n  -webkit-backdrop-filter: blur(3px) saturate(1.6) brightness(1.06);\n  backdrop-filter: blur(3px) saturate(1.6) brightness(1.06);\n  /* edge lighting: bright rim on top, soft coloured rims on the sides (like light bending at the edge) */\n  box-shadow:\n    inset 0 1px 0.5px rgba(255, 255, 255, 0.95),\n    inset 0 -1px 1px rgb(var(--a-deep-rgb) / 0.12),\n    inset 1.5px 0 1px rgba(150, 220, 255, 0.35),\n    inset -1.5px 0 1px rgba(160, 255, 210, 0.35),\n    inset 0 0 0 0.5px rgba(255, 255, 255, 0.6),\n    0 6px 18px rgb(var(--a-deep-rgb) / 0.16),\n    0 1px 3px rgb(var(--a-deep-rgb) / 0.10);\n}\n/* a highlight that slides across the glass while it moves */\n.liquid-shine {\n  background: linear-gradient(105deg, rgba(255, 255, 255, 0) 30%, rgba(255, 255, 255, 0.45) 48%, rgba(255, 255, 255, 0) 62%);\n  mix-blend-mode: soft-light;\n  opacity: 0.9;\n  transition: transform 0.12s linear;\n}\n[data-theme=\"dark\"] .liquid-glass {\n  background:\n    radial-gradient(120% 90% at 50% 0%, rgba(255, 255, 255, 0.14), rgba(255, 255, 255, 0) 60%),\n    linear-gradient(180deg, color-mix(in srgb, var(--a-tint-dark) 80%, white 12%), var(--a-tint-dark));\n  -webkit-backdrop-filter: blur(3px) saturate(1.5) brightness(1.15);\n  backdrop-filter: blur(3px) saturate(1.5) brightness(1.15);\n  box-shadow:\n    inset 0 1px 0.5px rgba(255, 255, 255, 0.28),\n    inset 0 -1px 1px rgba(0, 0, 0, 0.3),\n    inset 1.5px 0 1px rgba(120, 200, 255, 0.22),\n    inset -1.5px 0 1px rgba(120, 255, 200, 0.22),\n    inset 0 0 0 0.5px rgba(255, 255, 255, 0.14),\n    0 6px 18px rgba(0, 0, 0, 0.4);\n}\n[data-theme=\"dark\"] .liquid-shine { opacity: 0.5; }\n\n@supports not ((backdrop-filter: blur(1px)) or (-webkit-backdrop-filter: blur(1px))) {\n  .glass-bar { background: rgba(255, 255, 255, 0.96); }\n}\n@media (prefers-reduced-motion: reduce) {\n  .slide-from-right { animation: none; }\n}\n\n/* ===== Dark mode ===== */\n/* Same brand, night version: deep green-black background, soft light text, mint accents. */\n[data-theme=\"dark\"] {\n  --bg: var(--a-bg-dark);\n  --surface: var(--a-surface-dark);\n  --ink: #e8eeeb;\n  --ink-soft: #9fb0a9;\n  --line: var(--a-line-dark);\n  --forest: var(--a-forest-dark);\n  --forest-deep: var(--a-deep-dark);\n  /* --mint stays light: it's used for light text on the dark green cards */\n}\n[data-theme=\"dark\"] body { background: var(--bg); }\n\n/* Light-tinted backgrounds become dark green tints */\n[data-theme=\"dark\"] .bg-mint { background-color: var(--a-tint-dark); }\n[data-theme=\"dark\"] .bg-mint\\/60 { background-color: color-mix(in srgb, var(--a-tint-dark) 78%, transparent); }\n[data-theme=\"dark\"] .bg-mint\\/50 { background-color: color-mix(in srgb, var(--a-tint-dark) 62%, transparent); }\n/* Green text becomes brighter so it reads on dark */\n[data-theme=\"dark\"] .text-forest { color: var(--a-bright); }\n[data-theme=\"dark\"] .text-forest-deep:not([class*=\"bg-white\"]) { color: var(--a-soft); }\n[data-theme=\"dark\"] .ring-forest { --tw-ring-color: var(--a-bright); }\n/* Warning and error boxes */\n[data-theme=\"dark\"] .bg-red-50 { background-color: rgba(185, 28, 28, 0.18); }\n[data-theme=\"dark\"] .text-red-700, [data-theme=\"dark\"] .text-red-800 { color: #fca5a5; }\n[data-theme=\"dark\"] .bg-amber-50 { background-color: rgba(180, 120, 20, 0.18); }\n[data-theme=\"dark\"] .text-amber-800, [data-theme=\"dark\"] .text-amber-900 { color: #fcd34d; }\n/* Popup background stays dark (ink turns light in dark mode) */\n[data-theme=\"dark\"] .bg-ink\\/30 { background-color: rgba(0, 0, 0, 0.55); }\n\n/* Dark glass tab bar */\n[data-theme=\"dark\"] .glass-bar {\n  background: linear-gradient(180deg, rgba(30, 46, 40, 0.66), rgba(19, 31, 27, 0.5));\n  border-color: rgba(255, 255, 255, 0.08);\n  box-shadow:\n    0 10px 30px rgba(0, 0, 0, 0.45),\n    inset 0 1px 0 rgba(255, 255, 255, 0.08);\n}\n@supports not ((backdrop-filter: blur(1px)) or (-webkit-backdrop-filter: blur(1px))) {\n  [data-theme=\"dark\"] .glass-bar { background: rgba(19, 31, 27, 0.97); }\n}\n\n/* Switching themes: the new look grows out of a circle (set up in lib/theme.ts) */\n::view-transition-old(root),\n::view-transition-new(root) {\n  animation: none;\n  mix-blend-mode: normal;\n}\n\n/* Two-finger pinch is used for light/dark, so the app itself doesn't zoom */\n.tab-strip, .tab-panel, .overlay-page { touch-action: pan-x pan-y; }\n\n/* Discover ⇄ Community: the new section glides in from its side through frosted glass\n   (starts blurred and slightly transparent, then comes into focus) */\n@keyframes glass-from-right {\n  from { opacity: 0; transform: translateX(14%) scale(0.985); filter: blur(10px) saturate(1.4); }\n  60% { filter: blur(2px) saturate(1.1); }\n  to { opacity: 1; transform: none; filter: none; }\n}\n@keyframes glass-from-left {\n  from { opacity: 0; transform: translateX(-14%) scale(0.985); filter: blur(10px) saturate(1.4); }\n  60% { filter: blur(2px) saturate(1.1); }\n  to { opacity: 1; transform: none; filter: none; }\n}\n.glass-from-right { animation: glass-from-right 0.42s cubic-bezier(0.2, 0.8, 0.2, 1) backwards; }\n.glass-from-left { animation: glass-from-left 0.42s cubic-bezier(0.2, 0.8, 0.2, 1) backwards; }\n@media (prefers-reduced-motion: reduce) {\n  .glass-from-right, .glass-from-left { animation: none; }\n}\n\n/* Tab switching choices (Me → Tab switching). Opacity/transform only, so they're light on phones. */\n@keyframes tab-fade-through {\n  from { opacity: 0; transform: scale(1.02); }\n  to { opacity: 1; transform: none; }\n}\n@keyframes tab-slide-right {\n  from { opacity: 0; transform: translateX(30px); }\n  to { opacity: 1; transform: none; }\n}\n@keyframes tab-slide-left {\n  from { opacity: 0; transform: translateX(-30px); }\n  to { opacity: 1; transform: none; }\n}\n.tab-fade-through { animation: tab-fade-through 0.22s cubic-bezier(0.2, 0.8, 0.2, 1) backwards; }\n.tab-slide-right { animation: tab-slide-right 0.26s cubic-bezier(0.2, 0.8, 0.2, 1) backwards; }\n.tab-slide-left { animation: tab-slide-left 0.26s cubic-bezier(0.2, 0.8, 0.2, 1) backwards; }\n@media (prefers-reduced-motion: reduce) {\n  .tab-fade-through, .tab-slide-right, .tab-slide-left { animation: none; }\n}\n\n/* ===== Sign-in screens: one frosted-glass card over soft brand-colour light ===== */\n.auth-light {\n  position: fixed;\n  inset: 0;\n  z-index: -1;\n  pointer-events: none;\n  background:\n    radial-gradient(42% 34% at 12% 14%, rgb(var(--a-strong-rgb) / 0.55), transparent 72%),\n    radial-gradient(38% 30% at 92% 26%, rgb(var(--a-deep-rgb) / 0.35), transparent 72%),\n    radial-gradient(50% 38% at 70% 92%, rgb(var(--a-strong-rgb) / 0.35), transparent 72%),\n    radial-gradient(40% 30% at 8% 88%, rgb(var(--a-mint-rgb) / 0.9), transparent 72%),\n    var(--bg);\n}\n.glass-card {\n  background: linear-gradient(180deg, rgba(255, 255, 255, 0.74), rgba(255, 255, 255, 0.52));\n  -webkit-backdrop-filter: blur(26px) saturate(1.7);\n  backdrop-filter: blur(26px) saturate(1.7);\n  border: 1px solid rgba(255, 255, 255, 0.75);\n  box-shadow:\n    0 24px 60px rgb(var(--a-deep-rgb) / 0.16),\n    0 2px 8px rgb(var(--a-deep-rgb) / 0.06),\n    inset 0 1px 0 rgba(255, 255, 255, 0.9);\n}\n.glass-chip {\n  background: rgba(255, 255, 255, 0.6);\n  border: 1px solid rgba(255, 255, 255, 0.8);\n  box-shadow: 0 2px 8px rgb(var(--a-deep-rgb) / 0.08);\n}\n[data-theme=\"dark\"] .auth-light {\n  background:\n    radial-gradient(42% 34% at 12% 14%, rgb(var(--a-strong-rgb) / 0.22), transparent 72%),\n    radial-gradient(38% 30% at 92% 26%, color-mix(in srgb, var(--a-forest-dark) 45%, transparent), transparent 72%),\n    radial-gradient(50% 38% at 70% 92%, rgb(var(--a-strong-rgb) / 0.14), transparent 72%),\n    var(--bg);\n}\n[data-theme=\"dark\"] .glass-card {\n  background: linear-gradient(180deg, rgba(32, 48, 42, 0.62), rgba(17, 28, 24, 0.5));\n  border-color: rgba(255, 255, 255, 0.09);\n  box-shadow:\n    0 24px 60px rgba(0, 0, 0, 0.5),\n    inset 0 1px 0 rgba(255, 255, 255, 0.08);\n}\n[data-theme=\"dark\"] .glass-chip {\n  background: rgba(255, 255, 255, 0.06);\n  border-color: rgba(255, 255, 255, 0.1);\n  box-shadow: none;\n}\n@supports not ((backdrop-filter: blur(1px)) or (-webkit-backdrop-filter: blur(1px))) {\n  .glass-card { background: rgba(255, 255, 255, 0.95); }\n  [data-theme=\"dark\"] .glass-card { background: rgba(19, 31, 27, 0.97); }\n}\n",
  "src/app/page.tsx": "\"use client\";\n\nimport { useRouter } from \"next/navigation\";\nimport { account, accountLabel, useAccount } from \"@/lib/account/useAccount\";\nimport { stopSync } from \"@/lib/account/sync\";\nimport { setLang, useLang } from \"@/lib/me/lang\";\n\nconst copy = {\n  en: {\n    tagline: \"Your private companion for men's wellness\",\n    points: [\n      \"Daily activities that fit your life\",\n      \"Short lessons from trusted sources\",\n      \"A private space to track how you feel\",\n    ],\n    ageQuestion: \"This app talks openly about men's sexual health. By continuing you confirm you are 18 or older.\",\n    start: \"Get started\",\n    create: \"Create free account\",\n    login: \"I have an account · Log in\",\n    continue: \"Continue\",\n    signedInAs: \"Signed in as\",\n    notYou: \"Not you?\",\n    privacy: \"No sign-up needed to look around. Your data stays private.\",\n  },\n  sw: {\n    tagline: \"Mwenzako wa siri kwa afya ya mwanaume\",\n    points: [\n      \"Shughuli za kila siku zinazoendana na maisha yako\",\n      \"Masomo mafupi kutoka vyanzo vya kuaminika\",\n      \"Sehemu ya siri ya kufuatilia unavyojisikia\",\n    ],\n    ageQuestion: \"Programu hii inazungumzia afya ya uzazi ya mwanaume kwa uwazi. Kwa kuendelea unathibitisha una miaka 18 au zaidi.\",\n    start: \"Anza sasa\",\n    create: \"Fungua akaunti bure\",\n    login: \"Nina akaunti · Ingia\",\n    continue: \"Endelea\",\n    signedInAs: \"Umeingia kama\",\n    notYou: \"Si wewe?\",\n    privacy: \"Huhitaji kujisajili ili kuangalia. Taarifa zako ni siri.\",\n  },\n} as const;\n\nexport default function Welcome() {\n  const router = useRouter();\n  // The same language setting as the rest of the app (Me → Language), so a choice here carries everywhere\n  const lang = useLang();\n  const t = copy[lang];\n\n  // This page always stays here (no automatic redirect). If he's already signed in,\n  // the buttons change to \"Continue\" so he isn't asked to log in again.\n  const acc = useAccount();\n\n  /** Every choice confirms 18+ and saves the language, then goes in as a guest or to the account screen. */\n  function enter(to: string) {\n    try {\n      localStorage.setItem(\"ms_age_ok\", \"1\");\n    } catch {}\n    router.push(to);\n  }\n\n  return (\n    <main className=\"mx-auto flex min-h-dvh max-w-md flex-col px-5 pb-8 pt-6 lg:max-w-5xl lg:px-10 lg:pt-8\">\n      {/* Top bar: logo + language switch */}\n      <header className=\"rise flex items-center justify-between\">\n        <div className=\"flex items-center gap-2\">\n          <div className=\"flex h-9 w-9 items-center justify-center rounded-xl bg-forest text-sm font-bold text-mint\">\n            MS\n          </div>\n          <span className=\"text-base font-semibold\">Men&apos;s Social</span>\n        </div>\n        <div className=\"flex rounded-full bg-surface p-1 text-xs font-semibold ring-1 ring-line\">\n          {([\"en\", \"sw\"] as const).map((l) => (\n            <button\n              key={l}\n              onClick={() => setLang(l)}\n              className={`rounded-full px-3 py-1.5 transition-colors ${\n                lang === l ? \"bg-forest text-white\" : \"text-ink-soft\"\n              }`}\n              aria-pressed={lang === l}\n            >\n              {l.toUpperCase()}\n            </button>\n          ))}\n        </div>\n      </header>\n\n      {/* On a computer: the hero on the left, the way in on the right */}\n      {/* Phone and computer: the content sits in the middle of the screen (my-auto) */}\n      <div className=\"my-auto py-6 lg:grid lg:grid-cols-[1.25fr_1fr] lg:items-stretch lg:gap-6 lg:py-10\">\n      {/* Hero card */}\n      <section className=\"rise rise-2 rounded-3xl bg-forest-deep p-6 text-white lg:mt-0 lg:flex lg:flex-col lg:justify-center lg:p-12\">\n        <p className=\"text-sm text-mint-strong\">Kayani Men&apos;s Social</p>\n        <h1 className=\"mt-2 text-[28px] font-bold leading-tight lg:text-[44px]\">{t.tagline}</h1>\n        <ul className=\"mt-6 space-y-3 lg:mt-8 lg:space-y-4\">\n          {t.points.map((p) => (\n            <li key={p} className=\"flex items-start gap-3 text-sm text-mint lg:text-base\">\n              <span className=\"mt-1.5 h-2 w-2 shrink-0 rounded-full bg-mint-strong\" />\n              {p}\n            </li>\n          ))}\n        </ul>\n      </section>\n\n      {/* Age check + three ways in */}\n      <section className=\"rise rise-3 mt-4 rounded-3xl bg-surface p-5 ring-1 ring-line lg:mt-0 lg:flex lg:flex-col lg:justify-center lg:p-8\">\n        <p className=\"text-sm text-ink-soft\">{t.ageQuestion}</p>\n        {acc.status === \"signedIn\" ? (\n          <>\n            <button\n              onClick={() => enter(\"/social\")}\n              className=\"mt-4 w-full rounded-full bg-forest py-3.5 text-sm font-semibold text-white transition-transform active:scale-[0.98]\"\n            >\n              {t.continue}\n            </button>\n            <p className=\"mt-3 text-center text-xs text-ink-soft\">\n              {t.signedInAs} {accountLabel(acc.user)} ·{\" \"}\n              <button\n                onClick={async () => {\n                  // Another man on this phone: remove the signed-in man's data from it, then sign out\n                  stopSync({ clearPhone: true });\n                  await account.signOut();\n                }}\n                className=\"font-semibold text-forest\"\n              >\n                {t.notYou}\n              </button>\n            </p>\n          </>\n        ) : (\n          <>\n            <button\n              onClick={() => enter(\"/social\")}\n              className=\"mt-4 w-full rounded-full bg-forest py-3.5 text-sm font-semibold text-white transition-transform active:scale-[0.98]\"\n            >\n              {t.start}\n            </button>\n            <button\n              onClick={() => enter(\"/account?mode=signup&next=/social\")}\n              className=\"mt-2 w-full rounded-full bg-mint py-3.5 text-sm font-semibold text-forest-deep transition-transform active:scale-[0.98]\"\n            >\n              {t.create}\n            </button>\n            <button\n              onClick={() => enter(\"/account?mode=login&next=/social\")}\n              className=\"mt-2 w-full rounded-full bg-white py-3.5 text-sm font-semibold text-forest-deep shadow-sm ring-1 ring-black/5 transition-transform active:scale-[0.98]\"\n            >\n              {t.login}\n            </button>\n          </>\n        )}\n      </section>\n\n      </div>\n\n      <p className=\"rise rise-4 pt-2 text-center text-xs text-ink-soft\">{t.privacy}</p>\n    </main>\n  );\n}\n",
  "src/components/auth/AuthScreen.tsx": "\"use client\";\n\n// The sign-in screens (men's log in / sign up, new password, and the Studio): one frosted-glass card\n// in the middle of the screen, over soft brand-colour light. X at the top left closes it.\n\nimport Link from \"next/link\";\nimport { X } from \"lucide-react\";\n\nexport default function AuthScreen({\n  closeHref,\n  closeLabel,\n  title,\n  subtitle,\n  children,\n}: {\n  /** Where the X goes */\n  closeHref: string;\n  closeLabel: string;\n  /** Shown under the MS logo at the top of the card (default \"Men's Social\") */\n  title?: string;\n  subtitle?: string;\n  children: React.ReactNode;\n}) {\n  return (\n    <div className=\"auth-backdrop relative isolate min-h-dvh\">\n      <div aria-hidden className=\"auth-light\" />\n      <main className=\"mx-auto flex min-h-dvh w-full max-w-md flex-col justify-center px-4 py-6 sm:py-10\">\n        <div className=\"glass-card rise relative rounded-[32px] p-5 pt-4 sm:p-7 sm:pt-5\">\n          <Link\n            href={closeHref}\n            aria-label={closeLabel}\n            className=\"glass-chip absolute left-4 top-4 flex h-10 w-10 items-center justify-center rounded-full text-ink-soft transition-transform hover:text-ink active:scale-95 sm:left-5 sm:top-5\"\n          >\n            <X size={18} />\n          </Link>\n\n          <div className=\"flex flex-col items-center pb-5 text-center\">\n            <div className=\"flex h-11 w-11 items-center justify-center rounded-2xl bg-forest text-sm font-bold text-mint shadow-lg shadow-forest/25\">MS</div>\n            <p className=\"mt-2 text-sm font-bold leading-tight\">{title ?? \"Men's Social\"}</p>\n            {subtitle && <p className=\"text-[11px] text-ink-soft\">{subtitle}</p>}\n          </div>\n\n          {children}\n        </div>\n      </main>\n    </div>\n  );\n}\n",
  "src/components/motion/Toast.tsx": "\"use client\";\n\nimport { createContext, useCallback, useContext, useRef, useState } from \"react\";\n\ntype ToastState = { id: number; text: string; leaving: boolean } | null;\n\nconst ToastContext = createContext<(text: string) => void>(() => {});\n\n/** Call showToast(\"Saved\") from any screen inside the app. */\nexport function useToast() {\n  return useContext(ToastContext);\n}\n\n/** sidebar: the page has the desktop sidebar on the left, so the toast centres on the space beside it. */\nexport function ToastProvider({ children, sidebar = true }: { children: React.ReactNode; sidebar?: boolean }) {\n  const [toast, setToast] = useState<ToastState>(null);\n  const timers = useRef<ReturnType<typeof setTimeout>[]>([]);\n\n  const showToast = useCallback((text: string) => {\n    timers.current.forEach(clearTimeout);\n    const id = Date.now();\n    setToast({ id, text, leaving: false });\n    timers.current = [\n      setTimeout(() => setToast((t) => (t && t.id === id ? { ...t, leaving: true } : t)), 2200),\n      setTimeout(() => setToast((t) => (t && t.id === id ? null : t)), 2500),\n    ];\n  }, []);\n\n  return (\n    <ToastContext.Provider value={showToast}>\n      {children}\n      {toast && (\n        <div\n          key={toast.id}\n          role=\"status\"\n          className={`fixed bottom-24 left-1/2 z-50 lg:bottom-8 ${sidebar ? \"lg:left-[calc(50%+8rem)]\" : \"\"} whitespace-nowrap rounded-full bg-forest-deep px-5 py-2.5 text-sm font-medium text-white shadow-lg ${\n            toast.leaving ? \"toast-out\" : \"toast-in\"\n          }`}\n        >\n          {toast.text}\n        </div>\n      )}\n    </ToastContext.Provider>\n  );\n}\n",
  "src/components/studio/StudioGate.tsx": "\"use client\";\n\nimport { useEffect, useRef, useState } from \"react\";\nimport { Copy, Eye, EyeOff, KeyRound, Loader2, LogOut, ShieldAlert, ShieldCheck, Smartphone } from \"lucide-react\";\nimport Captcha, { captchaOn, type CaptchaHandle } from \"@/components/security/Captcha\";\nimport AuthScreen from \"@/components/auth/AuthScreen\";\nimport type { AdminState } from \"@/lib/studio/useAdmin\";\nimport { staffName } from \"@/lib/studio/username\";\nimport type { AdminRole } from \"@/lib/admin/perms\";\n\nexport type StudioAdmin = {\n  email: string;\n  userId: string;\n  role: AdminRole;\n  displayName: string | null;\n};\n\n/** What staff see before they're inside: sign-in form, or a clear message. */\ntype SetupResult = { factorId: string; qr: string; secret: string } | { error: string };\n\nexport function GateScreen({\n  state,\n  onSignIn,\n  onSignOut,\n  onStartSetup,\n  onVerify,\n}: {\n  state: Exclude<AdminState, { status: \"admin\" }>;\n  onSignIn: (login: string, password: string, captchaToken?: string) => Promise<string | null>;\n  onSignOut: () => void;\n  onStartSetup: () => Promise<SetupResult>;\n  onVerify: (factorId: string, code: string) => Promise<string | null>;\n}) {\n  // One frosted-glass card in the middle of the screen; X goes back to the men's log-in page\n  const signedIn = state.status === \"notAdmin\" || state.status === \"mfaSetup\" || state.status === \"mfaCode\";\n  return (\n    <AuthScreen closeHref=\"/account\" closeLabel=\"Back to the app log-in\" title=\"Admin Control Center\" subtitle=\"Men's Social · staff only\">\n      <div className=\"space-y-4\">\n        {state.status === \"loading\" && (\n          <div className=\"flex justify-center py-12 text-ink-soft\" aria-busy=\"true\" aria-label=\"Loading\">\n            <Loader2 className=\"animate-spin\" />\n          </div>\n        )}\n        {state.status === \"unconfigured\" && (\n          <Message title=\"Supabase isn't connected\">\n            Add <code>.env.local</code> with <code>NEXT_PUBLIC_SUPABASE_URL</code> and <code>NEXT_PUBLIC_SUPABASE_ANON_KEY</code> next to\n            package.json, then stop and restart <code>npx next dev</code>.\n          </Message>\n        )}\n        {state.status === \"error\" && <Message title=\"Something went wrong\">{state.message}</Message>}\n        {state.status === \"signedOut\" && <LoginForm onSignIn={onSignIn} />}\n        {state.status === \"mfaSetup\" && <SetupTwoStep email={state.email} onStart={onStartSetup} onVerify={onVerify} />}\n        {state.status === \"mfaCode\" && <CodeForm email={state.email} factorId={state.factorId} onVerify={onVerify} />}\n        {state.status === \"notAdmin\" && (\n          <Message title=\"No admin access\">\n            {staffName(state.email)} is signed in, but isn&apos;t an admin. Ask an owner to add this account in Settings → Admins.\n          </Message>\n        )}\n        {signedIn && (\n          <button onClick={onSignOut} className=\"mx-auto flex items-center gap-1.5 rounded-full px-3 py-2 text-xs font-semibold text-ink-soft\">\n            <LogOut size={14} /> Sign out\n          </button>\n        )}\n      </div>\n    </AuthScreen>\n  );\n}\n\n/** A message inside the sign-in card. */\nfunction Message({ title, children }: { title: string; children: React.ReactNode }) {\n  return (\n    <div className=\"flex gap-3 rounded-2xl bg-bg/60 p-4\">\n      <ShieldAlert size={18} className=\"mt-0.5 shrink-0 text-forest\" />\n      <div>\n        <p className=\"font-semibold\">{title}</p>\n        <div className=\"mt-1 text-sm text-ink-soft\">{children}</div>\n      </div>\n    </div>\n  );\n}\n\nfunction LoginForm({ onSignIn }: { onSignIn: (login: string, password: string, captchaToken?: string) => Promise<string | null> }) {\n  const [login, setLogin] = useState(\"\");\n  const [password, setPassword] = useState(\"\");\n  const [show, setShow] = useState(false);\n  const [busy, setBusy] = useState(false);\n  const [error, setError] = useState<string | null>(null);\n  const [captcha, setCaptcha] = useState<string | null>(null);\n  const captchaBox = useRef<CaptchaHandle>(null);\n\n  async function submit(e: React.FormEvent) {\n    e.preventDefault();\n    if (captchaOn && !captcha) return setError(\"Please complete the check that you're a person, then try again.\");\n    setBusy(true);\n    setError(null);\n    const err = await onSignIn(login, password, captcha ?? undefined);\n    captchaBox.current?.reset();\n    setBusy(false);\n    if (err) setError(err);\n  }\n\n  return (\n    <form onSubmit={submit} className=\"space-y-4\">\n      <div className=\"text-center\">\n        <h1 className=\"text-xl font-bold\">Sign in</h1>\n        <p className=\"mt-1 text-sm text-ink-soft\">For Kayani staff who run Men&apos;s Social.</p>\n      </div>\n      <label className=\"block\">\n        <span className=\"text-xs font-semibold text-ink-soft\">Username or email</span>\n        <input\n          type=\"text\"\n          autoComplete=\"username\"\n          autoCapitalize=\"none\"\n          autoCorrect=\"off\"\n          spellCheck={false}\n          placeholder=\"e.g. TheAdmin\"\n          required\n          value={login}\n          onChange={(e) => setLogin(e.target.value)}\n          className=\"mt-1 w-full rounded-2xl bg-surface px-4 py-3 text-sm outline-none ring-1 ring-line focus:ring-2 focus:ring-forest\"\n        />\n      </label>\n      <label className=\"block\">\n        <span className=\"text-xs font-semibold text-ink-soft\">Password</span>\n        <div className=\"relative mt-1\">\n          <input\n            type={show ? \"text\" : \"password\"}\n            autoComplete=\"current-password\"\n            required\n            value={password}\n            onChange={(e) => setPassword(e.target.value)}\n            className=\"w-full rounded-2xl bg-surface px-4 py-3 pr-11 text-sm outline-none ring-1 ring-line focus:ring-2 focus:ring-forest\"\n          />\n          <button\n            type=\"button\"\n            onClick={() => setShow((s) => !s)}\n            aria-label={show ? \"Hide password\" : \"Show password\"}\n            className=\"absolute inset-y-0 right-0 flex w-11 items-center justify-center text-ink-soft\"\n          >\n            {show ? <EyeOff size={16} /> : <Eye size={16} />}\n          </button>\n        </div>\n      </label>\n      <Captcha ref={captchaBox} onToken={setCaptcha} />\n      {error && (\n        <p role=\"alert\" className=\"rounded-2xl bg-red-50 px-3 py-2 text-sm text-red-700\">\n          {error}\n        </p>\n      )}\n      <button\n        disabled={busy}\n        className=\"flex w-full items-center justify-center gap-2 rounded-full bg-forest py-3.5 text-sm font-semibold text-white transition-transform active:scale-[0.98] disabled:opacity-60\"\n      >\n        {busy && <Loader2 size={16} className=\"animate-spin\" />} Sign in\n      </button>\n      <p className=\"flex items-center justify-center gap-1.5 text-[11px] text-ink-soft\">\n        <ShieldCheck size={12} /> Next, you&apos;ll enter a code from your authenticator app.\n      </p>\n    </form>\n  );\n}\n\n/** First time: scan a QR code with an authenticator app, then type the 6-digit code it shows. */\nfunction SetupTwoStep({ email, onStart, onVerify }: { email: string; onStart: () => Promise<SetupResult>; onVerify: (factorId: string, code: string) => Promise<string | null> }) {\n  const [setup, setSetup] = useState<SetupResult | null>(null);\n  const [showKey, setShowKey] = useState(false);\n  const started = useRef(false);\n\n  useEffect(() => {\n    if (started.current) return; // once (React runs effects twice in development)\n    started.current = true;\n    void onStart().then(setSetup);\n  }, [onStart]);\n\n  return (\n    <div className=\"space-y-4\">\n      <div className=\"flex items-start gap-3\">\n        <span className=\"flex h-10 w-10 shrink-0 items-center justify-center rounded-2xl bg-mint text-forest\">\n          <ShieldCheck size={20} />\n        </span>\n        <div>\n          <h1 className=\"text-xl font-bold\">Turn on two-step sign-in</h1>\n          <p className=\"mt-1 text-sm text-ink-soft\">\n            Staff accounts can see private data, so a password alone isn&apos;t enough. This is a one-time set-up for {staffName(email)}.\n          </p>\n        </div>\n      </div>\n\n      <ol className=\"space-y-1.5 text-sm\">\n        <li className=\"flex gap-2\">\n          <Smartphone size={16} className=\"mt-0.5 shrink-0 text-forest\" />\n          <span>\n            <b>1.</b> On your phone, install an authenticator app: <b>Google Authenticator</b> or <b>Microsoft Authenticator</b> (free).\n          </span>\n        </li>\n        <li className=\"pl-6\">\n          <b>2.</b> In the app, tap <b>+</b> and scan this code.\n        </li>\n        <li className=\"pl-6\">\n          <b>3.</b> Type the 6-digit code the app shows.\n        </li>\n      </ol>\n\n      {!setup ? (\n        <div className=\"flex h-48 items-center justify-center text-ink-soft\" aria-busy=\"true\" aria-label=\"Loading\">\n          <Loader2 className=\"animate-spin\" />\n        </div>\n      ) : \"error\" in setup ? (\n        <p role=\"alert\" className=\"rounded-2xl bg-red-50 px-3 py-2 text-sm text-red-700\">\n          {setup.error}\n        </p>\n      ) : (\n        <>\n          <div className=\"flex flex-col items-center gap-2\">\n            {/* The QR code comes from Supabase as an image (it holds the secret, so it's never stored) */}\n            {/* eslint-disable-next-line @next/next/no-img-element */}\n            <img src={setup.qr} alt=\"QR code for your authenticator app\" width={176} height={176} className=\"rounded-2xl bg-white p-2 ring-1 ring-line\" />\n            <button type=\"button\" onClick={() => setShowKey((v) => !v)} className=\"flex items-center gap-1 text-xs font-semibold text-forest\">\n              <KeyRound size={13} /> {showKey ? \"Hide the key\" : \"Can't scan? Type a key instead\"}\n            </button>\n            {showKey && (\n              <div className=\"flex w-full items-center gap-2 rounded-2xl bg-bg px-3 py-2\">\n                <code className=\"flex-1 break-all text-xs\">{setup.secret}</code>\n                <button\n                  type=\"button\"\n                  aria-label=\"Copy key\"\n                  onClick={() => void navigator.clipboard?.writeText(setup.secret)}\n                  className=\"flex h-8 w-8 shrink-0 items-center justify-center rounded-full ring-1 ring-line\"\n                >\n                  <Copy size={14} />\n                </button>\n              </div>\n            )}\n          </div>\n          <CodeInput factorId={setup.factorId} onVerify={onVerify} button=\"Turn on and continue\" />\n          <p className=\"text-[11px] text-ink-soft\">\n            Lost your phone later? The owner can reset it in Supabase → Authentication → Users → your account → remove the authenticator.\n            Then you set it up again here.\n          </p>\n        </>\n      )}\n    </div>\n  );\n}\n\n/** Every sign-in after set-up: the code from the app. */\nfunction CodeForm({ email, factorId, onVerify }: { email: string; factorId: string; onVerify: (factorId: string, code: string) => Promise<string | null> }) {\n  return (\n    <div className=\"space-y-4\">\n      <div className=\"text-center\">\n        <h1 className=\"text-xl font-bold\">Enter your code</h1>\n        <p className=\"mt-1 text-sm text-ink-soft\">\n          Open your authenticator app and type the 6-digit code for Men&apos;s Social ({staffName(email)}).\n        </p>\n      </div>\n      <CodeInput factorId={factorId} onVerify={onVerify} button=\"Continue\" />\n    </div>\n  );\n}\n\nfunction CodeInput({ factorId, onVerify, button }: { factorId: string; onVerify: (factorId: string, code: string) => Promise<string | null>; button: string }) {\n  const [code, setCode] = useState(\"\");\n  const [busy, setBusy] = useState(false);\n  const [error, setError] = useState<string | null>(null);\n\n  async function submit(e: React.FormEvent) {\n    e.preventDefault();\n    if (code.length !== 6) return setError(\"The code has 6 digits.\");\n    setBusy(true);\n    setError(null);\n    const err = await onVerify(factorId, code);\n    setBusy(false);\n    if (err) {\n      setError(err);\n      setCode(\"\");\n    }\n  }\n\n  return (\n    <form onSubmit={submit} className=\"space-y-3\">\n      <label className=\"block\">\n        <span className=\"text-xs font-semibold text-ink-soft\">6-digit code</span>\n        <input\n          inputMode=\"numeric\"\n          autoComplete=\"one-time-code\"\n          autoFocus\n          maxLength={6}\n          value={code}\n          onChange={(e) => setCode(e.target.value.replace(/\\D/g, \"\"))}\n          className=\"mt-1 w-full rounded-2xl bg-surface px-4 py-3 text-center text-xl tracking-[0.5em] outline-none ring-1 ring-line focus:ring-2 focus:ring-forest\"\n        />\n      </label>\n      {error && (\n        <p role=\"alert\" className=\"rounded-2xl bg-red-50 px-3 py-2 text-sm text-red-700\">\n          {error}\n        </p>\n      )}\n      <button\n        disabled={busy}\n        className=\"flex w-full items-center justify-center gap-2 rounded-full bg-forest py-3.5 text-sm font-semibold text-white transition-transform active:scale-[0.98] disabled:opacity-60\"\n      >\n        {busy && <Loader2 size={16} className=\"animate-spin\" />} {button}\n      </button>\n    </form>\n  );\n}\n\nexport function Notice({ title, children }: { title: string; children: React.ReactNode }) {\n  return (\n    <div className=\"mx-auto flex max-w-sm gap-3 rounded-3xl bg-surface p-5 ring-1 ring-line\">\n      <ShieldAlert size={18} className=\"mt-0.5 shrink-0 text-forest\" />\n      <div>\n        <p className=\"font-semibold\">{title}</p>\n        <div className=\"mt-1 text-sm text-ink-soft\">{children}</div>\n      </div>\n    </div>\n  );\n}\n"
};

for (const path of remove) {
  rmSync(path, { force: true });
  console.log("removed", path);
}
rmSync("src/app/(app)/account", { recursive: true, force: true });
for (const [path, content] of Object.entries(files)) {
  mkdirSync(dirname(path), { recursive: true });
  writeFileSync(path, content);
  console.log("wrote", path);
}
// The old build cache still points at the old page locations
rmSync(".next", { recursive: true, force: true });
console.log("\nStep 32 done. Next: npm test, then npm run dev.");
